"""Complete rbtree type and public helper headers."""
ROWS = []


def add(path, title, intro, principle, use, sections, questions):
    ROWS.append(dict(path=path, title=title, intro=intro, principle=principle,
                     use=use, area='균형 이진 트리 · 포인터 태깅 · 중복 키 · RCU',
                     sections=sections, questions=questions))


add('include/linux/rbtree_types.h', '레드블랙 트리 타입 전체: 부모·색상 결합과 선택적 최소값 캐시',
    '트리 노드, 일반 루트, 최소값을 캐시한 루트의 메모리 표현을 정의합니다.',
    '노드는 부모·색상 정보를 담는 unsigned long 하나와 좌우 자식 포인터를 가집니다. 캐시 루트는 일반 루트에 왼쪽 끝 포인터를 더합니다.',
    '이 헤더의 구조체만으로 균형이나 수명이 보장되지 않습니다. 연결·회전·색상 관리 API와 함께 사용합니다.',
    [('전체 구성', 'SPDX와 guard 뒤에 rb_node, rb_root, rb_root_cached, 두 빈 루트 매크로, endif가 있습니다. 다른 헤더를 직접 포함하지 않으며 NULL 같은 이름은 사용 문맥에서 정의되어 있어야 합니다.'),
     ('노드 표현', 'rb_node는 __rb_parent_color, rb_right, rb_left 순서입니다. unsigned long 크기의 정렬 속성을 명시하며 주석은 CRIS의 필요성을 언급합니다. 부모 포인터와 색상 관련 비트의 실제 마스킹은 다른 헤더에서 수행하므로 이 필드를 평범한 부모 주소로 바로 역참조하면 안 됩니다.'),
     ('일반 루트와 캐시 루트', 'rb_root는 루트 노드 포인터 하나입니다. rb_root_cached는 일반 루트와 rb_leftmost를 가지며 최대값 캐시는 없습니다. 원문은 오른쪽 끝 캐시의 추가 메모리에 비해 수혜 사용처가 적다고 설계 이유를 설명하고 필요하면 사용자가 별도로 구현할 수 있다고 합니다.'),
     ('초기값과 CS', 'RB_ROOT는 NULL 루트, RB_ROOT_CACHED는 루트와 최소값 모두 NULL인 compound literal입니다. 초기값 대입은 기존 객체를 해제하는 동작이 아닙니다. 태그 비트와 정렬, 메모리 비용과 조회 비용의 교환, 최소 자료형과 알고리즘 분리를 학습합니다.')],
    [('rb_root_cached가 최대값도 캐시하는가?', '아니다. 왼쪽 끝 포인터만 추가한다', '그렇다. 양 끝을 항상 캐시한다', '선언에는 rb_root와 rb_leftmost만 있습니다. 오른쪽 끝은 공간 비용과 사용처를 고려해 제외했다고 주석이 설명합니다.'),
     ('__rb_parent_color를 그대로 부모 포인터로 사용해도 되는가?', '안 된다. 상태 비트를 제거하는 접근자를 사용해야 한다', '된다. 이름만 다를 뿐 순수한 포인터다', '부모와 색상 정보가 결합된 unsigned long입니다. rbtree.h의 rb_parent는 하위 비트를 마스킹합니다.')])

add('include/linux/rbtree.h', '레드블랙 트리 인터페이스 전체: 연결·캐시·중복 검색·RCU 한계',
    '트리 노드 접근과 연결, 외부 균형 함수 선언, 비교 콜백 기반 삽입·검색 helper를 제공합니다.',
    '키 순서 결정과 트리 균형 복구를 분리합니다. 새 노드를 올바른 빈 링크에 연결한 뒤 색상·회전을 관리하는 함수를 호출합니다.',
    '일관된 비교 관계와 객체 수명·동기화를 호출자가 보장합니다. RCU helper도 동시 회전 중 검색의 완전성을 보장하지 않는다는 원문 경고를 지켜야 합니다.',
    [('파일 전체 구성', 'SPDX와 역사적 설명, guard와 container_of/rbtree_types/stddef/rcupdate 포함 뒤에 부모·객체·빈 상태 매크로가 있습니다. 균형·순회·교체 외부 선언, 일반/RCU 연결과 safe 객체 변환, 후위 순회, 캐시 wrapper, 비교 연산 계약, 추가·중복 추가·검색·중복 순회 helper로 끝납니다. 실제 회전 함수 본문은 이 헤더에 없습니다.'),
     ('부모와 미연결 표식', 'rb_parent는 __rb_parent_color의 하위2비트를 ~3으로 지운 뒤 부모 포인터로 바꿉니다. RB_EMPTY_ROOT는 READ_ONCE로 루트 NULL 여부를 봅니다. RB_CLEAR_NODE는 부모·색상 필드에 자기 주소를 저장하고 RB_EMPTY_NODE는 그 값인지 확인합니다. 이 표식은 특정 트리 소속을 검색하지 않으며 일반 rb_erase를 불렀다고 자동 복구되는 계약으로 가정하면 안 됩니다.'),
     ('포함 객체와 NULL', 'rb_entry는 container_of이고 rb_entry_safe는 입력을 임시 변수에 한 번 저장하여 NULL이면 NULL, 아니면 포함 객체를 반환합니다. safe라는 이름은 NULL 처리에 관한 것이며 임의로 해제된 포인터의 수명을 보호하지 않습니다.'),
     ('외부 API 선언', 'rb_insert_color와 rb_erase가 균형 유지·삭제를 담당합니다. next/prev/first/last는 중위 순서, first_postorder/next_postorder는 자식 뒤 부모를 방문하는 순서를 제공합니다. replace_node와 replace_node_rcu는 제거·재삽입 없이 노드를 교체하는 API이며 정렬 위치에 맞는 키를 유지하는 등 교체 계약이 필요합니다. 선언만으로 모든 키 변경이 안전하다고 추측하지 않습니다.'),
     ('연결과 공개 순서', 'rb_link_node는 부모 필드를 저장하고 좌우 자식을 NULL로 만든 뒤 *rb_link에 새 노드를 씁니다. rcu 버전은 마지막 공개에 rcu_assign_pointer를 사용합니다. 이 두 함수 자체는 색상 균형 복구를 호출하지 않습니다. 부모와 링크 위치는 호출자가 올바르게 찾아 전달해야 합니다.'),
     ('후위 safe 순회의 제한', 'rbtree_postorder_for_each_entry_safe는 현재 객체 처리 전에 다음 후위 노드를 계산합니다. 현재 객체의 메모리를 무효화하는 처리를 허용하지만 rb_erase처럼 트리를 재균형해 순서를 바꾸는 작업까지 허용하지 않습니다. 원문은 이런 변경이 일부 노드를 놓치게 할 수 있다고 경고합니다.'),
     ('캐시 삽입과 최소값', 'rb_first_cached는 rb_leftmost를 직접 읽습니다. insert_color_cached는 leftmost가 true이면 캐시를 갱신한 뒤 일반 균형 함수를 호출합니다. leftmost 플래그는 호출자가 계산하거나 rb_add_cached가 탐색 과정에서 계산합니다. 잘못된 플래그는 캐시의 의미를 깨뜨립니다.'),
     ('캐시 삭제와 교체', 'erase_cached는 삭제 노드가 최소이면 삭제 전에 rb_next로 새 최소를 구해 캐시에 저장하고 일반 삭제를 호출합니다. 반환값은 최소 노드가 바뀐 경우의 새 최소 또는 NULL입니다. NULL은 비최소 삭제일 수도 있고 마지막 노드 삭제일 수도 있습니다. replace_node_cached는 victim이 최소일 때 캐시를 new로 바꾼 뒤 일반 교체를 합니다.'),
     ('두 비교 규약', 'less는 노드 두 개를 비교하는 bool이고 cmp는 음수/0/양수 결과를 냅니다. 검색용 cmp는 키 포인터와 노드 포인터를 받아 큰 임시 객체를 만들 필요가 없습니다. 삽입과 검색에서 비교 관계가 일관되어야 하며 동등한 노드가 여러 개면 일반 find가 어느 것을 반환할지 보장하지 않습니다.'),
     ('일반·캐시 삽입', 'rb_add는 less이면 왼쪽, 아니면 오른쪽으로 내려가 빈 링크에 연결하고 균형을 복구합니다. 같은 키도 삽입할 수 있습니다. rb_add_cached도 같은 탐색을 하며 오른쪽으로 간 적이 있으면 leftmost=false입니다. 새 최소일 때 새 노드 포인터, 아니면 NULL을 반환하며 NULL도 정상 삽입 결과입니다.'),
     ('찾거나 추가', 'rb_find_add는 cmp0인 기존 노드를 발견하면 그 포인터를 반환하고 새 노드를 연결하지 않습니다. 끝까지 없으면 연결·균형 복구 후 NULL을 반환합니다. rcu 버전은 연결 공개를 rb_link_node_rcu로 바꿉니다. 삽입에 실패했다는 의미의 NULL이 아니며 두 경우의 새 객체 소유권을 호출자가 처리해야 합니다.'),
     ('일반 검색과 RCU 검색', 'rb_find는 키와 현재 노드를 비교해 한쪽 자식으로 내려가거나 일치 노드를 반환합니다. rb_find_rcu는 자식 접근에 rcu_dereference_raw를 쓰지만 동시 트리 회전 중 내려가는 경로가 일치를 놓칠 수 있다고 명시합니다. NULL 결과가 모든 동시 상황에서 키 부재를 증명하는 것은 아닙니다. 이 helper에 읽기 잠금·객체 회수 정책 전체가 포함된 것도 아닙니다.'),
     ('첫 일치와 같은 키 순회', 'rb_find_first는 cmp0이면 후보를 저장하고 계속 왼쪽을 탐색해 가장 왼쪽 일치를 찾습니다. rb_next_match는 rb_next로 한 번 이동하고 cmp가0이 아니면 NULL입니다. rb_for_each는 이 둘을 조합해 같은 키의 인접한 중위 구간을 순회합니다. 비교 관계와 트리 순서가 맞아야 동등한 키의 구간 의미가 유지됩니다.'),
     ('역사적 주석과 현재 코드', '파일 앞의 오래된 설명은 삽입·검색 핵심을 직접 작성해 콜백 비용을 피하는 방식을 강조하지만 파일 뒤에는 콜백 기반 helper가 실제로 존재합니다. 서두만 보고 콜백을 전혀 지원하지 않는다고 결론 내리지 않습니다. __always_inline helper의 최적화 가능성과 실제 호출 비용은 빌드 결과에 달려 있습니다.'),
     ('CS 연결과 검증 범위', '이진 검색 순서와 균형 조건의 분리, 포인터 태깅, 중복 키·lower-bound형 탐색, 캐시 일관성, 후위 순회와 재균형, 메모리 수명과 검색 완전성의 차이를 학습합니다. 전체 헤더 경로를 대조했으며 외부 회전 구현이나 실제 RCU 경쟁을 실행 검증한 것으로 세지 않습니다.')],
    [('rb_link_node만 호출하면 균형 복구도 완료되는가?', '아니다. 연결 후 별도 균형 함수가 필요하다', '그렇다. 내부에서 회전까지 수행한다', '본문은 부모·자식과 링크 포인터를 설정할 뿐입니다. rb_add 같은 wrapper가 이어서 rb_insert_color를 호출합니다.'),
     ('후위 safe 순회에서 rb_erase를 자유롭게 호출해도 되는가?', '안 된다. 재균형으로 방문 순서가 바뀔 수 있다', '된다. safe가 모든 트리 변경을 허용한다', '원문 주석은 현재 메모리 무효화와 트리 재정렬을 구분하고 rb_erase로 노드를 놓칠 수 있다고 명시합니다.'),
     ('rb_find_add가 NULL을 반환하면?', '일치 노드가 없어 새 노드를 삽입한 경우다', '메모리 할당 실패로 삽입하지 못한 경우다', '이 helper는 객체를 할당하지 않습니다. 일치하면 기존 포인터를 반환하고 새 삽입 경로 끝에서 NULL을 반환합니다.'),
     ('rb_find_rcu의 NULL은 동시 회전 중 키 부재의 완전한 증명인가?', '아니다. 회전 경쟁으로 false negative가 가능하다', '그렇다. RCU 이름이 완전한 스냅샷을 보장한다', '함수 주석에 동시 회전과 탐색의 불완전성이 명시되어 있습니다. 객체 수명 보호와 탐색 결과 완전성은 다릅니다.'),
     ('같은 키 중 가장 왼쪽 노드를 찾으려면?', 'rb_find_first를 사용한다', 'rb_find가 항상 가장 왼쪽을 반환한다', '일반 find는 처음 만난 동등 노드에서 끝납니다. find_first는 일치 후보를 저장하고 왼쪽 탐색을 계속합니다.')])
